class Solution {
  public boolean circularArrayLoop(int[] nums) {
    int n = nums.length;
    for (int i = 0; i < n; i++) {
      if (nums[i] == 0) continue;
      int slow = i, fast = next(nums, i);
      // move while every step keeps the same direction as the start
      while (nums[fast] * nums[i] > 0 && nums[next(nums, fast)] * nums[i] > 0) {
        if (slow == fast) {
          if (slow == next(nums, slow)) break; // a self-loop does not count
          return true;
        }
        slow = next(nums, slow);
        fast = next(nums, next(nums, fast));
      }
      // nothing reachable from i in this direction forms a loop: clear it
      int sign = nums[i];
      for (int j = i; nums[j] * sign > 0; ) {
        int nxt = next(nums, j);
        nums[j] = 0;
        j = nxt;
      }
    }
    return false;
  }

  private int next(int[] nums, int i) {
    int n = nums.length;
    return ((i + nums[i]) % n + n) % n;
  }
}
